package io.github.rebrowser.continuity;

import android.app.Application;
import io.github.rebrowser.bootstrap.StartupCoordinator;
import java.io.*;
import java.nio.channels.FileChannel;
import java.nio.file.*;
import java.nio.file.attribute.*;
import java.util.*;

/** Bounded native COLD-only exact v2 old-epoch ownership inventory. No content reads, path/alias
 * strings from IPC, global cache cleanup or recursion into other apps/public storage. Unknown
 * namespaces/shared Gecko profiles/other epochs/symlinks fail BEFORE destructive marker. This
 * restricted path does not pretend arbitrary warm Gecko/native owners are quiescent. */
public final class PrivateEpochManifest {
    public static final int MAX_NODES=16384,MAX_DEPTH=8;public static final long MAX_BYTES=8L*1024*1024*1024;
    private static final class Node {final Path path;final Object key;final boolean directory;final long size;Node(Path p,BasicFileAttributes a){path=p;key=a.fileKey();directory=a.isDirectory();size=a.size();}}
    private final Path data,noBackup,epochs,oldRoot;private final List<Node> nodes;private final Object dataKey,noBackupKey,epochsKey;private final byte[] epoch;private final Map<Path,Object> ownedDirectoryKeys=new HashMap<>();private boolean erasureAttempted;
    private PrivateEpochManifest(Path data,Path noBackup,Path epochs,Path oldRoot,List<Node> nodes,byte[] epoch)throws IOException{this.data=data;this.noBackup=noBackup;this.epochs=epochs;this.oldRoot=oldRoot;this.nodes=Collections.unmodifiableList(nodes);this.epoch=epoch.clone();for(Node n:nodes)if(n.directory)ownedDirectoryKeys.put(n.path,n.key);dataKey=directory(data).fileKey();noBackupKey=directory(noBackup).fileKey();epochsKey=directory(epochs).fileKey();}
    static PrivateEpochManifest captureNativeCold(Application nativeApplication,ContinuityCoordinator.Context consumedNativeContext,StartupCoordinator.ColdContinuityFence actualColdFence)throws IOException{if(nativeApplication==null || consumedNativeContext==null || actualColdFence==null)throw new IllegalArgumentException("Native cold erasure context required");actualColdFence.requireStillCold(nativeApplication);return captureOwnedColdPaths(nativeApplication.getDataDir().toPath(),consumedNativeContext.oldEpoch(),()->actualColdFence.requireStillCold(nativeApplication));}
    // Private HOST reflection fixture supplies its OWN generated paths/guard, not OS/owner evidence.
    private static PrivateEpochManifest captureOwnedColdPaths(Path nativeData,byte[] oldEpoch,Runnable actualColdGuard)throws IOException{
        if(nativeData==null || !nativeData.isAbsolute() || oldEpoch==null || oldEpoch.length!=16 || actualColdGuard==null)throw new IllegalArgumentException("Native ownership bounds required");actualColdGuard.run();Path data=nativeData.normalize(),noBackup=data.resolve("no_backup"),epochs=noBackup.resolve("owned-epochs-v1"),old=epochs.resolve(hex(oldEpoch));directory(data);directory(noBackup);directory(epochs);requireColdExternalNamespaces(data,noBackup,epochs,old);
        List<Node> nodes=new ArrayList<>();long[] bytes={0};walk(old,old,nodes,bytes,0);actualColdGuard.run();return new PrivateEpochManifest(data,noBackup,epochs,old,nodes,oldEpoch);
    }
    public int ownedNodeCount(){return nodes.size();}public long ownedFileBytes(){long n=0;for(Node node:nodes)if(!node.directory)n+=node.size;return n;}
    List<String> nativeEpochKeyAliases(){return Collections.singletonList(nativeWrappingAlias(epoch));}
    static String nativeWrappingAlias(byte[] epoch){if(epoch==null || epoch.length!=16)throw new IllegalArgumentException("Native epoch key scope required");return "io.github.rebrowser.datawrap.v1."+hex(epoch);} // DEVICE_INSTALL/signers are NOT epoch-owned DATA_WRAP.
    Path newEpochPath(byte[] freshNativeEpoch)throws IOException{if(freshNativeEpoch==null || freshNativeEpoch.length!=16 || Arrays.equals(freshNativeEpoch,epoch))throw new IOException("Fresh native epoch required");requireAnchors();Path result=epochs.resolve(hex(freshNativeEpoch));if(exists(result))throw new IOException("Candidate native epoch already exists; no overwrite/merge");return result;}
    void requireUnchangedSnapshot()throws IOException{requireAnchors();requireColdExternalNamespaces(data,noBackup,epochs,oldRoot);List<Node> now=new ArrayList<>();walk(oldRoot,oldRoot,now,new long[]{0},0);if(now.size()!=nodes.size())throw new IOException("Native owned namespace membership changed");for(int i=0;i<now.size();i++){Node a=nodes.get(i),b=now.get(i);if(!a.path.equals(b.path) || !a.key.equals(b.key) || a.directory!=b.directory || (!a.directory && a.size!=b.size))throw new IOException("Native owned namespace changed");}}
    void deleteExactOwnedNodes(Runnable actualNativeCurrent)throws IOException{if(erasureAttempted || actualNativeCurrent==null)throw new IOException("Native epoch erasure attempt unavailable");erasureAttempted=true;requireAnchors();List<Node> reverse=new ArrayList<>(nodes);Collections.reverse(reverse);for(Node node:reverse){actualNativeCurrent.run();requireAnchors();requireOwnedParents(node.path);BasicFileAttributes now=attrs(node.path);if(!node.key.equals(now.fileKey()) || now.isDirectory()!=node.directory || (!node.directory && (!now.isRegularFile() || now.size()!=node.size)))throw new IOException("Owned native erasure node changed");Files.delete(node.path);}force(epochs);verifyOldRootAbsent();actualNativeCurrent.run();}
    void verifyOldRootAbsent()throws IOException{requireAnchors();if(exists(oldRoot))throw new IOException("Old native epoch namespace not empty");}
    Object createFreshEmptyEpoch(byte[] fresh,Runnable actualNativeCurrent)throws IOException{actualNativeCurrent.run();verifyOldRootAbsent();Path next=newEpochPath(fresh);Files.createDirectory(next,PosixFilePermissions.asFileAttribute(PosixFilePermissions.fromString("rwx------")));force(epochs);BasicFileAttributes a=directory(next);requireEmpty(next);actualNativeCurrent.run();return a.fileKey();}
    void verifyFreshEmptyEpoch(byte[] fresh,Object exactNewKey)throws IOException{verifyOldRootAbsent();Path next=epochs.resolve(hex(fresh));BasicFileAttributes a=directory(next);if(exactNewKey==null || !exactNewKey.equals(a.fileKey()))throw new IOException("Fresh native epoch ownership changed");requireEmpty(next);requireColdExternalNamespaces(data,noBackup,epochs,next);}
    private void requireOwnedParents(Path child)throws IOException{for(Path p=child.getParent();p!=null && p.startsWith(oldRoot);p=p.getParent()){Object expected=ownedDirectoryKeys.get(p);if(expected==null || !expected.equals(directory(p).fileKey()))throw new IOException("Native old-epoch parent replaced");}}
    private void requireAnchors()throws IOException{if(!dataKey.equals(directory(data).fileKey()) || !noBackupKey.equals(directory(noBackup).fileKey()) || !epochsKey.equals(directory(epochs).fileKey()))throw new IOException("Native epoch parent replaced");}
    private static void walk(Path root,Path path,List<Node> nodes,long[] bytes,int depth)throws IOException{if(depth>MAX_DEPTH || nodes.size()>=MAX_NODES)throw new IOException("Native epoch manifest bounds exceeded");BasicFileAttributes a=attrs(path);if(a.fileKey()==null || (!a.isRegularFile() && !a.isDirectory()))throw new IOException("Unknown/nonregular native epoch node");String relative=root.relativize(path).toString().replace(java.io.File.separatorChar,'/');if(!ownedRelative(relative,a.isDirectory()))throw new IOException("Unknown native epoch ownership shape");if(!a.isDirectory()){if(a.size()<0 || a.size()>MAX_BYTES-bytes[0])throw new IOException("Native epoch logical byte budget exceeded");bytes[0]+=a.size();}nodes.add(new Node(path,a));if(a.isDirectory()){List<Path> children=new ArrayList<>();try(DirectoryStream<Path> stream=Files.newDirectoryStream(path)){for(Path child:stream){if(children.size()>=MAX_NODES-nodes.size())throw new IOException("Native epoch child budget exceeded");children.add(child);}}children.sort(Comparator.comparing(p->p.getFileName().toString()));for(Path child:children)walk(root,child,nodes,bytes,depth+1);}}
    private static boolean ownedRelative(String name,boolean dir){if(name.isEmpty())return dir;String[] p=name.split("/",-1);if(p[0].equals("private-records-v1"))return p.length==1?dir:p.length==2 && !dir && (p[1].equals(".private-records.lock") || p[1].matches("p[1-6]_[0-9a-f]{32}\\.v1(\\.pending)?"));if(p[0].equals("apk-staging-v1"))return p.length==1?dir:p.length==2 && !dir && (p[1].equals(".apk.lock") || p[1].matches("[0-9a-f]{64}\\.(apk|pending)"));if(p[0].equals("mail-objects-v1"))return p.length==1?dir:p.length==2?p[1].matches("[0-9a-f]{32}") && dir:p.length==3 && p[1].matches("[0-9a-f]{32}") && !dir && (p[2].equals(".objects.lock") || p[2].matches("[0-9a-f]{32}(\\.pending)?"));return false;} // Mail DB paths not yet pinned: unknown DB namespace FAILS, never guessed.
    private static void requireColdExternalNamespaces(Path data,Path noBackup,Path epochs,Path onlyEpoch)throws IOException{
        Set<String> emptyNames=new HashSet<>(Arrays.asList("files","cache","code_cache","databases","shared_prefs"));try(DirectoryStream<Path> entries=Files.newDirectoryStream(data)){for(Path p:entries){String n=p.getFileName().toString();if(n.equals("no_backup"))continue;if(!emptyNames.contains(n))throw new IOException("Unknown app-owned namespace needs independent erasure qualification");directory(p);requireEmpty(p);}}
        try(DirectoryStream<Path> entries=Files.newDirectoryStream(noBackup)){for(Path p:entries){String n=p.getFileName().toString();if(n.equals("source-bootstrap-v1")){directory(p);try(DirectoryStream<Path> metadata=Files.newDirectoryStream(p)){for(Path node:metadata){String file=node.getFileName().toString();BasicFileAttributes a=attrs(node);if((!file.equals("source-continuity.v1") && !file.equals("source-continuity.pending") && !file.equals("source-continuity.lock")) || !a.isRegularFile() || a.fileKey()==null || a.size()>216)throw new IOException("Unknown native bootstrap ownership");}}continue;}if(!n.equals("owned-epochs-v1"))throw new IOException("Unknown private no-backup ownership");}}
        try(DirectoryStream<Path> entries=Files.newDirectoryStream(epochs)){for(Path p:entries)if(!p.equals(onlyEpoch))throw new IOException("Other native epochs need explicit integrity recovery");}
    }
    private static BasicFileAttributes directory(Path p)throws IOException{BasicFileAttributes a=attrs(p);if(!a.isDirectory() || a.fileKey()==null)throw new IOException("Existing identifiable native directory required");return a;}
    private static BasicFileAttributes attrs(Path p)throws IOException{return Files.readAttributes(p,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);}
    private static boolean exists(Path p)throws IOException{try{attrs(p);return true;}catch(NoSuchFileException missing){return false;}}
    private static void requireEmpty(Path p)throws IOException{try(DirectoryStream<Path> d=Files.newDirectoryStream(p)){if(d.iterator().hasNext())throw new IOException("Native namespace still contains data; cold-only erasure denied");}}
    private static void force(Path directory)throws IOException{try(FileChannel c=FileChannel.open(directory,StandardOpenOption.READ)){c.force(true);}}
    private static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(Character.forDigit((b&255)>>>4,16)).append(Character.forDigit(b&15,16));return s.toString();}
}
